import React, { useCallback, useEffect, useState } from 'react';
import {
  AppBar,
  Avatar,
  Badge,
  Box,
  Button,
  CircularProgress,
  Container,
  Divider,
  Tab,
  Tabs,
  Toolbar,
  Tooltip,
  Typography,
} from '@mui/material';
import RefreshIcon from '@mui/icons-material/Refresh';
import DashboardIcon from '@mui/icons-material/Dashboard';
import AssignmentIndIcon from '@mui/icons-material/AssignmentInd';
import RateReviewIcon from '@mui/icons-material/RateReview';

import SummaryCards from './components/SummaryCards';
import AssignedPRsTable from './components/AssignedPRsTable';
import ReviewPRsTable from './components/ReviewPRsTable';
import RepositoryGroupWidget from './components/RepositoryGroupWidget';
import {
  fetchAssignedPullRequests,
  fetchCurrentUser,
  fetchDashboardSummary,
  fetchRepositoryGroupSummary,
  fetchReviewPullRequests,
} from './api/pullRequestApi';
import type { DashboardSummary, PullRequest, RepositoryGroupSummary, UserInfo } from './types/PullRequest';

/** Wraps a tab label with a count badge. */
const TabLabel: React.FC<{ label: string; count: number; loading: boolean; badgeColor?: 'primary' | 'warning' }> = ({
  label,
  count,
  loading,
  badgeColor = 'primary',
}) => (
  <Box display="flex" alignItems="center" gap={1.5}>
    {label}
    <Badge
      badgeContent={loading ? '…' : count}
      color={badgeColor}
      showZero
      sx={{ '& .MuiBadge-badge': { position: 'relative', transform: 'none', fontSize: '0.7rem' } }}
    />
  </Box>
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState(0);

  const [currentUser, setCurrentUser] = useState<UserInfo | null>(null);
  const [summary, setSummary] = useState<DashboardSummary | null>(null);
  const [assignedPRs, setAssignedPRs] = useState<PullRequest[]>([]);
  const [reviewPRs, setReviewPRs] = useState<PullRequest[]>([]);
  const [groupSummary, setGroupSummary] = useState<RepositoryGroupSummary | null>(null);

  const [summaryLoading, setSummaryLoading] = useState(false);
  const [assignedLoading, setAssignedLoading] = useState(false);
  const [reviewLoading, setReviewLoading] = useState(false);
  const [groupLoading, setGroupLoading] = useState(false);

  const [assignedError, setAssignedError] = useState<string | null>(null);
  const [reviewError, setReviewError] = useState<string | null>(null);
  const [groupError, setGroupError] = useState<string | null>(null);

  const isAnyLoading = summaryLoading || assignedLoading || reviewLoading || groupLoading;

  // ── Data fetching ──────────────────────────────────────────────────────
  const loadAll = useCallback(() => {
    // Fetch user identity once — skip if already loaded
    if (!currentUser) {
      fetchCurrentUser()
        .then(setCurrentUser)
        .catch((err) => console.error('User fetch failed:', err));
    }

    setSummaryLoading(true);
    fetchDashboardSummary()
      .then(setSummary)
      .catch((err) => console.error('Summary fetch failed:', err))
      .finally(() => setSummaryLoading(false));

    setAssignedLoading(true);
    setAssignedError(null);
    fetchAssignedPullRequests()
      .then(setAssignedPRs)
      .catch((err) => {
        console.error('Assigned PRs fetch failed:', err);
        setAssignedError('Failed to load your pull requests.');
      })
      .finally(() => setAssignedLoading(false));

    setReviewLoading(true);
    setReviewError(null);
    fetchReviewPullRequests()
      .then(setReviewPRs)
      .catch((err) => {
        console.error('Review PRs fetch failed:', err);
        setReviewError('Failed to load pull requests awaiting review.');
      })
      .finally(() => setReviewLoading(false));

    setGroupLoading(true);
    setGroupError(null);
    fetchRepositoryGroupSummary()
      .then(setGroupSummary)
      .catch((err) => {
        console.error('Repository group fetch failed:', err);
        setGroupError('Failed to load repository group summary.');
      })
      .finally(() => setGroupLoading(false));
  }, []);

  useEffect(() => {
    loadAll();
  }, [loadAll]);

  // ── Render ─────────────────────────────────────────────────────────────
  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh', bgcolor: '#f5f6fa' }}>
      {/* Top AppBar */}
      <AppBar position="static" elevation={2}>
        <Toolbar>
          <DashboardIcon sx={{ mr: 1.5 }} />
          <Typography variant="h6" component="div" sx={{ flexGrow: 1, fontWeight: 700 }}>
            Azure DevOps Dashboard
          </Typography>
          <Button
            variant="outlined"
            color="inherit"
            startIcon={isAnyLoading ? <CircularProgress size={16} color="inherit" /> : <RefreshIcon />}
            onClick={loadAll}
            disabled={isAnyLoading}
          >
            {isAnyLoading ? 'Refreshing…' : 'Refresh'}
          </Button>

          {/* Current user */}
          {currentUser && (
            <Tooltip title={currentUser.displayName}>
              <Box display="flex" alignItems="center" gap={1} ml={2}>
                <Avatar sx={{ width: 30, height: 30, fontSize: '0.85rem', bgcolor: 'primary.light' }}>
                  {currentUser.displayName.split(' ').map((n) => n[0]).join('').slice(0, 2).toUpperCase()}
                </Avatar>
                <Typography variant="body2" color="inherit" sx={{ display: { xs: 'none', sm: 'block' } }}>
                  {currentUser.displayName}
                </Typography>
              </Box>
            </Tooltip>
          )}
        </Toolbar>
      </AppBar>

      {/* Main Content */}
      <Container maxWidth="xl" sx={{ py: 4, flexGrow: 1 }}>
        {/* Summary cards */}
        <SummaryCards summary={summary} loading={summaryLoading} />

        <Divider sx={{ my: 3 }} />

        {/* Repository group widget */}
        <Typography variant="subtitle1" fontWeight={700} mb={1.5} color="text.secondary">
          Repository Groups
        </Typography>
        <RepositoryGroupWidget
          summary={groupSummary}
          loading={groupLoading}
          error={groupError}
          assignedPRs={assignedPRs}
          reviewPRs={reviewPRs}
        />

        <Divider sx={{ my: 3 }} />

        {/* Tabs */}
        <Box sx={{ bgcolor: 'white', borderRadius: 1, boxShadow: 2 }}>
          <Tabs
            value={activeTab}
            onChange={(_, v) => setActiveTab(v)}
            sx={{ borderBottom: 1, borderColor: 'divider', px: 2 }}
            textColor="primary"
            indicatorColor="primary"
          >
            <Tab
              icon={<AssignmentIndIcon fontSize="small" />}
              iconPosition="start"
              label={
                <TabLabel
                  label="My Pull Requests"
                  count={assignedPRs.length}
                  loading={assignedLoading}
                />
              }
              sx={{ textTransform: 'none', fontWeight: 600, minHeight: 56 }}
            />
            <Tab
              icon={<RateReviewIcon fontSize="small" />}
              iconPosition="start"
              label={
                <TabLabel
                  label="Awaiting My Review"
                  count={reviewPRs.length}
                  loading={reviewLoading}
                />
              }
              sx={{ textTransform: 'none', fontWeight: 600, minHeight: 56 }}
            />
          </Tabs>

          {/* Tab panels */}
          <Box sx={{ p: 3 }}>
            {activeTab === 0 && (
              <AssignedPRsTable
                pullRequests={assignedPRs}
                loading={assignedLoading}
                error={assignedError}
              />
            )}
            {activeTab === 1 && (
              <ReviewPRsTable
                pullRequests={reviewPRs}
                loading={reviewLoading}
                error={reviewError}
              />
            )}
          </Box>
        </Box>
      </Container>

      {/* Footer */}
      <Box
        component="footer"
        sx={{ py: 2, textAlign: 'center', bgcolor: 'white', borderTop: '1px solid #e0e0e0' }}
      >
        <Typography variant="caption" color="text.secondary">
          Azure DevOps Personal Dashboard · Phase 1
        </Typography>
      </Box>
    </Box>
  );
};

export default App;

import React, { useCallback, useEffect, useState } from 'react';
import {
  AppBar,
  Avatar,
  Badge,
  Box,
  Button,
  CircularProgress,
  Container,
  Divider,
  Tab,
  Tabs,
  Toolbar,
  Tooltip,
  Typography,
} from '@mui/material';
import RefreshIcon from '@mui/icons-material/Refresh';
import DashboardIcon from '@mui/icons-material/Dashboard';
import AssignmentIndIcon from '@mui/icons-material/AssignmentInd';
import RateReviewIcon from '@mui/icons-material/RateReview';

import SummaryCards from './components/SummaryCards';
import AssignedPRsTable from './components/AssignedPRsTable';
import ReviewPRsTable from './components/ReviewPRsTable';
import RepositoryGroupWidget from './components/RepositoryGroupWidget';
import {
  fetchAssignedPullRequests,
  fetchCurrentUser,
  fetchDashboardSummary,
  fetchRepositoryGroupSummary,
  fetchReviewPullRequests,
} from './api/pullRequestApi';
import type { DashboardSummary, PullRequest, RepositoryGroupSummary, UserInfo } from './types/PullRequest';

/** Wraps a tab label with a count badge. */
const TabLabel: React.FC<{ label: string; count: number; loading: boolean; badgeColor?: 'primary' | 'warning' }> = ({
  label,
  count,
  loading,
  badgeColor = 'primary',
}) => (
  <Box display="flex" alignItems="center" gap={1.5}>
    {label}
    <Badge
      badgeContent={loading ? '…' : count}
      color={badgeColor}
      showZero
      sx={{ '& .MuiBadge-badge': { position: 'relative', transform: 'none', fontSize: '0.7rem' } }}
    />
  </Box>
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState(0);

  const [currentUser, setCurrentUser] = useState<UserInfo | null>(null);
  const [summary, setSummary] = useState<DashboardSummary | null>(null);
  const [assignedPRs, setAssignedPRs] = useState<PullRequest[]>([]);
  const [reviewPRs, setReviewPRs] = useState<PullRequest[]>([]);
  const [groupSummary, setGroupSummary] = useState<RepositoryGroupSummary | null>(null);

  const [summaryLoading, setSummaryLoading] = useState(false);
  const [assignedLoading, setAssignedLoading] = useState(false);
  const [reviewLoading, setReviewLoading] = useState(false);
  const [groupLoading, setGroupLoading] = useState(false);

  const [assignedError, setAssignedError] = useState<string | null>(null);
  const [reviewError, setReviewError] = useState<string | null>(null);
  const [groupError, setGroupError] = useState<string | null>(null);

  const isAnyLoading = summaryLoading || assignedLoading || reviewLoading || groupLoading;

  // ── Data fetching ──────────────────────────────────────────────────────
  const loadAll = useCallback(() => {
    // Fetch user identity once — skip if already loaded
    if (!currentUser) {
      fetchCurrentUser()
        .then(setCurrentUser)
        .catch((err) => console.error('User fetch failed:', err));
    }

    setSummaryLoading(true);
    fetchDashboardSummary()
      .then(setSummary)
      .catch((err) => console.error('Summary fetch failed:', err))
      .finally(() => setSummaryLoading(false));

    setAssignedLoading(true);
    setAssignedError(null);
    fetchAssignedPullRequests()
      .then(setAssignedPRs)
      .catch((err) => {
        console.error('Assigned PRs fetch failed:', err);
        setAssignedError('Failed to load your pull requests.');
      })
      .finally(() => setAssignedLoading(false));

    setReviewLoading(true);
    setReviewError(null);
    fetchReviewPullRequests()
      .then(setReviewPRs)
      .catch((err) => {
        console.error('Review PRs fetch failed:', err);
        setReviewError('Failed to load pull requests awaiting review.');
      })
      .finally(() => setReviewLoading(false));

    setGroupLoading(true);
    setGroupError(null);
    fetchRepositoryGroupSummary()
      .then(setGroupSummary)
      .catch((err) => {
        console.error('Repository group fetch failed:', err);
        setGroupError('Failed to load repository group summary.');
      })
      .finally(() => setGroupLoading(false));
  }, []);

  useEffect(() => {
    loadAll();
  }, [loadAll]);

  // ── Render ─────────────────────────────────────────────────────────────
  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh', bgcolor: '#f5f6fa' }}>
      {/* Top AppBar */}
      <AppBar position="static" elevation={2}>
        <Toolbar>
          <DashboardIcon sx={{ mr: 1.5 }} />
          <Typography variant="h6" component="div" sx={{ flexGrow: 1, fontWeight: 700 }}>
            Azure DevOps Dashboard
          </Typography>
          <Button
            variant="outlined"
            color="inherit"
            startIcon={isAnyLoading ? <CircularProgress size={16} color="inherit" /> : <RefreshIcon />}
            onClick={loadAll}
            disabled={isAnyLoading}
          >
            {isAnyLoading ? 'Refreshing…' : 'Refresh'}
          </Button>

          {/* Current user */}
          {currentUser && (
            <Tooltip title={currentUser.displayName}>
              <Box display="flex" alignItems="center" gap={1} ml={2}>
                <Avatar sx={{ width: 30, height: 30, fontSize: '0.85rem', bgcolor: 'primary.light' }}>
                  {currentUser.displayName.split(' ').map((n) => n[0]).join('').slice(0, 2).toUpperCase()}
                </Avatar>
                <Typography variant="body2" color="inherit" sx={{ display: { xs: 'none', sm: 'block' } }}>
                  {currentUser.displayName}
                </Typography>
              </Box>
            </Tooltip>
          )}
        </Toolbar>
      </AppBar>

      {/* Main Content */}
      <Container maxWidth="xl" sx={{ py: 4, flexGrow: 1 }}>
        {/* Summary cards */}
        <SummaryCards summary={summary} loading={summaryLoading} />

        <Divider sx={{ my: 3 }} />

        {/* Repository group widget */}
        <Typography variant="subtitle1" fontWeight={700} mb={1.5} color="text.secondary">
          Repository Groups
        </Typography>
        <RepositoryGroupWidget
          summary={groupSummary}
          loading={groupLoading}
          error={groupError}
          assignedPRs={assignedPRs}
          reviewPRs={reviewPRs}
        />

        <Divider sx={{ my: 3 }} />

        {/* Tabs */}
        <Box sx={{ bgcolor: 'white', borderRadius: 1, boxShadow: 2 }}>
          <Tabs
            value={activeTab}
            onChange={(_, v) => setActiveTab(v)}
            textColor="inherit"
            sx={{
              borderBottom: 1,
              borderColor: 'divider',
              px: 2,
              '& .MuiTabs-indicator': {
                backgroundColor: activeTab === 1 ? 'warning.main' : 'primary.main',
              },
            }}
          >
            <Tab
              icon={<AssignmentIndIcon fontSize="small" />}
              iconPosition="start"
              label={
                <TabLabel
                  label="My Pull Requests"
                  count={assignedPRs.length}
                  loading={assignedLoading}
                  badgeColor="primary"
                />
              }
              sx={{
                textTransform: 'none',
                fontWeight: 600,
                minHeight: 56,
                color: 'text.secondary',
                '&.Mui-selected': { color: 'primary.main' },
              }}
            />
            <Tab
              icon={<RateReviewIcon fontSize="small" />}
              iconPosition="start"
              label={
                <TabLabel
                  label="Awaiting My Review"
                  count={reviewPRs.length}
                  loading={reviewLoading}
                  badgeColor="warning"
                />
              }
              sx={{
                textTransform: 'none',
                fontWeight: 600,
                minHeight: 56,
                color: 'text.secondary',
                '&.Mui-selected': { color: 'warning.main' },
              }}
            />
          </Tabs>

          {/* Tab panels */}
          <Box sx={{ p: 3 }}>
            {activeTab === 0 && (
              <AssignedPRsTable
                pullRequests={assignedPRs}
                loading={assignedLoading}
                error={assignedError}
              />
            )}
            {activeTab === 1 && (
              <ReviewPRsTable
                pullRequests={reviewPRs}
                loading={reviewLoading}
                error={reviewError}
              />
            )}
          </Box>
        </Box>
      </Container>

      {/* Footer */}
      <Box
        component="footer"
        sx={{ py: 2, textAlign: 'center', bgcolor: 'white', borderTop: '1px solid #e0e0e0' }}
      >
        <Typography variant="caption" color="text.secondary">
          Azure DevOps Personal Dashboard · Phase 1
        </Typography>
      </Box>
    </Box>
  );
};

export default App;

package com.personal.azuredashboard.client.model;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonProperty;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

import java.util.List;

/**
 * Represents a single Pull Request from the Azure DevOps Git API response.
 */
@Getter
@Setter
@NoArgsConstructor
@JsonIgnoreProperties(ignoreUnknown = true)
public class AzurePullRequest {

    private int pullRequestId;
    private String title;
    private String status;
    private String creationDate;
    private String mergeStatus;   // succeeded | conflicts | rejectedByPolicy | queued | notSet | failure
    private boolean isDraft;
    private Repository repository;
    private Identity createdBy;
    private Identity autoCompleteSetBy;
    private List<Reviewer> reviewers;
    private CompletionOptions completionOptions;

    /** Field-level @JsonProperty required for Jackson to deserialise "_links". */
    @JsonProperty("_links")
    private Links links;

    // ── Nested types ───────────────────────────────────────────────────────

    @Getter @Setter @NoArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class Repository {
        private String name;
        private String id;
        private String url;
        private ProjectDetails project;
    }

    public record ProjectDetails(String id, String name) {}

    @Getter @Setter @NoArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class Identity {
        private String displayName;
        private String id;
        private String uniqueName;
    }

    /**
     * isRequired=true → reviewer's approval is mandatory to complete the PR.
     * vote: 10=Approved, 5=ApprovedWithSuggestions, 0=NoVote, -5=WaitingForAuthor, -10=Rejected
     */
    @Getter @Setter @NoArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class Reviewer {
        private String id;
        private String displayName;
        private boolean isRequired;
        private int vote;
    }

    /** Merge completion options set when auto-complete is configured. */
    @Getter @Setter @NoArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class CompletionOptions {
        private boolean deleteSourceBranch;
        private boolean squashMerge;
        /** noFastForward | squash | rebase | rebaseMerge */
        private String mergeStrategy;
    }

    @Getter @Setter @NoArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class Links {
        private Href web;
    }

    @Getter @Setter @NoArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class Href {
        private String href;
    }
}

package com.personal.azuredashboard.client.model;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonProperty;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

import java.util.List;

/**
 * Represents a single Pull Request from the Azure DevOps Git API response.
 */
@Getter
@Setter
@NoArgsConstructor
@JsonIgnoreProperties(ignoreUnknown = true)
public class AzurePullRequest {

    private int pullRequestId;
    private String title;
    private String status;
    private String creationDate;
    private String mergeStatus;   // succeeded | conflicts | rejectedByPolicy | queued | notSet | failure
    private boolean isDraft;
    private Repository repository;
    private Identity createdBy;
    private Identity autoCompleteSetBy;
    private List<Reviewer> reviewers;
    private CompletionOptions completionOptions;

    /** Field-level @JsonProperty required for Jackson to deserialise "_links". */
    @JsonProperty("_links")
    private Links links;

    // ── Nested types ───────────────────────────────────────────────────────

    @Getter @Setter @NoArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class Repository {
        private String name;
        private String id;
        private String url;
        private ProjectDetails project;
    }

    public record ProjectDetails(String id, String name) {}

    @Getter @Setter @NoArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class Identity {
        private String displayName;
        private String id;
        private String uniqueName;
    }

    /**
     * isRequired=true → reviewer's approval is mandatory to complete the PR.
     * vote: 10=Approved, 5=ApprovedWithSuggestions, 0=NoVote, -5=WaitingForAuthor, -10=Rejected
     */
    @Getter @Setter @NoArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class Reviewer {
        private String id;
        private String displayName;
        private boolean isRequired;
        private int vote;
    }

    /** Merge completion options set when auto-complete is configured. */
    @Getter @Setter @NoArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class CompletionOptions {
        private boolean deleteSourceBranch;
        private boolean squashMerge;
        /** noFastForward | squash | rebase | rebaseMerge */
        private String mergeStrategy;
        /** When true, linked work items are automatically closed on PR completion. */
        private boolean transitionWorkItems;
    }

    @Getter @Setter @NoArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class Links {
        private Href web;
    }

    @Getter @Setter @NoArgsConstructor
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class Href {
        private String href;
    }
}

package com.personal.azuredashboard.controller;

import com.personal.azuredashboard.model.DashboardSummaryDto;
import com.personal.azuredashboard.model.PullRequestDto;
import com.personal.azuredashboard.service.PullRequestService;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

/**
 * REST controller that exposes Azure DevOps pull request data to the React frontend.
 *
 * @RestController already serialises return values to JSON with HTTP 200 —
 * no need to wrap in ResponseEntity unless status codes or headers need to vary.
 *
 * @CrossOrigin allows the React dev server (port 5173) to call these endpoints
 * during local development. In production the React app is served by Spring Boot
 * itself (same origin) so CORS is not strictly needed, but it does not hurt.
 */
@RestController
@RequestMapping("/api")
@CrossOrigin(origins = {"http://localhost:5173", "http://localhost:3000"})
public class PullRequestController {

    private final PullRequestService pullRequestService;

    public PullRequestController(PullRequestService pullRequestService) {
        this.pullRequestService = pullRequestService;
    }

    /**
     * Returns active pull requests created by the authenticated user.
     * GET /api/pullrequests/assigned
     */
    @GetMapping("/pullrequests/assigned")
    public List<PullRequestDto> getAssignedPullRequests() {
        return pullRequestService.getAssignedPullRequests();
    }

    /**
     * Returns active pull requests where the authenticated user is a reviewer.
     * GET /api/pullrequests/review
     */
    @GetMapping("/pullrequests/review")
    public List<PullRequestDto> getReviewPullRequests() {
        return pullRequestService.getReviewPullRequests();
    }

    /**
     * Returns dashboard summary: PR counts + last refresh timestamp.
     * GET /api/dashboard/summary
     */
    @GetMapping("/dashboard/summary")
    public DashboardSummaryDto getDashboardSummary() {
        return pullRequestService.getSummary();
    }
}

